export function aggregateScopes(
  records: readonly ScopeRecord[],
): ReadonlyMap<string, readonly string[]> {
  const grouped = new Map<string, string[]>();

  for (const record of records) {
    let scopes = grouped.get(record.principal);
    if (scopes === undefined) {
      scopes = [];
      grouped.set(record.principal, scopes);
    }
    scopes.push(...record.scopes);
