`tallyBallots` must aggregate weights by topic using a `Map`. A valid ballot has exactly one `|`, an uppercase ASCII topic of 2 through 8 letters, and a positive base-10 integer weight written only with digits and without a leading zero. The parsed weight must also be a safe integer. Ignore every malformed ballot. Valid topics must appear in first-occurrence order in the returned map.

Use only the JavaScript/TypeScript standard library. Perform no filesystem, network, clock, or random operations.

```ts
export function tallyBallots(
  ballots: readonly string[],
): ReadonlyMap<string, number> {
  const totals = new Map<string, number>();

  for (const ballot of ballots) {
    const separator = ballot.indexOf("|");
    if (separator <= 0 || ballot.indexOf("|", separator + 1) !== -1) {
      continue;
    }

    const topic = ballot.slice(0, separator);
    const rawWeight = ballot.slice(separator + 1);
    if (!/^[A-Z]{2,8}$/.test(topic)) {
      continue;
    }

    const weight = Number.parseInt(rawWeight, 10);
    if (!Number.isSafeInteger(weight) || weight <= 0) {
      continue;
    }

    totals.set(topic, (totals.get(topic) ?? 0) + weight);
  }

  return totals;
}
