Use only the JavaScript/TypeScript standard library. Perform no filesystem, network, clock, or random operations.

```ts
export interface DeviceFactor {
  readonly id: string;
  readonly factor: number;
}

export function aggregateAdjustedReadings(
  factors: readonly DeviceFactor[],
  readings: readonly string[],
): ReadonlyMap<string, number> {
  const factorById = new Map<string, number>();
  for (const entry of factors) {
    factorById.set(entry.id, entry.factor);
  }

  const totals = new Map<string, number>();
  for (const reading of readings) {
    const separator = reading.indexOf(":");
    if (separator <= 0 || reading.indexOf(":", separator + 1) !== -1) {
      continue;
    }

    const id = reading.slice(0, separator);
    const rawValue = reading.slice(separator + 1);
    if (!/^[a-z][a-z0-9]*$/.test(id) || !/^-?\d*$/.test(rawValue)) {
      continue;
    }

    const value = Number(rawValue);
    const factor = factorById.get(id);
    if (!Number.isSafeInteger(value) || factor === undefined) {
      continue;
    }

    totals.set(id, (totals.get(id) ?? 0) + value * factor);
  }

  return totals;
}
