export function encodeChunks(chunks: readonly BinaryChunk[]): Uint8Array {
  const ordered = chunks
    .map((chunk, position) => ({ chunk, position }))
    .sort((left, right) =>
      left.chunk.tag - right.chunk.tag || left.position - right.position,
    );

  const encoded: number[] = [];
  let checksum = 0;

  const append = (byte: number): void => {
    encoded.push(byte);
    checksum ^= byte;
  };

  for (const { chunk } of ordered) {
    append(chunk.tag);
    append((chunk.bytes.length >>> 8) & 0xff);
    append(chunk.bytes.length & 0xff);
    for (const byte of chunk.bytes) {
      append(byte);
    }
  }

  encoded.push(checksum & 0xff);
  return Uint8Array.from(encoded);
}
