function assertArrayEqual<T>(actual: readonly T[], expected: readonly T[], message: string): void {
  assert(actual.length === expected.length, `${message}: length`);
  for (let i = 0; i < expected.length; i += 1) {
    assert(actual[i] === expected[i], `${message}: index ${i}`);
  }
}

const empty = aggregateScopes([]);
assert(empty.size === 0, "empty input should produce an empty map");

const alphaFirst = ["read", "write", "read"];
const betaScopes = ["audit"];
const alphaSecond = ["admin", "write"];
const gammaScopes: string[] = [];
const records: ScopeRecord[] = [
  { principal: "alpha", scopes: alphaFirst },
  { principal: "beta", scopes: betaScopes },
  { principal: "alpha", scopes: alphaSecond },
  { principal: "gamma", scopes: gammaScopes },
];
const originalRecords = records.slice();
const originalScopes = records.map((record) => record.scopes.slice());

const result = aggregateScopes(records);
assertArrayEqual(Array.from(result.keys()), ["alpha", "beta", "gamma"], "principal order");
assertArrayEqual(result.get("alpha") ?? [], ["read", "write", "read", "admin", "write"], "aggregated alpha scopes");
assertArrayEqual(result.get("beta") ?? [], ["audit"], "single beta scope");
assertArrayEqual(result.get("gamma") ?? [], [], "empty gamma scopes");
assert(result.get("alpha") !== alphaFirst, "alpha bucket must not alias its first input array");
assert(result.get("alpha") !== alphaSecond, "alpha bucket must not alias its second input array");
assert(result.get("beta") !== betaScopes, "single-record bucket must be newly allocated");
assert(result.get("gamma") !== gammaScopes, "empty single-record bucket must be newly allocated");

assertArrayEqual(records, originalRecords, "record array must retain order and references");
for (let i = 0; i < records.length; i += 1) {
  assertArrayEqual(records[i].scopes, originalScopes[i], `input scopes ${i} must not be mutated`);
}

alphaFirst.push("later");
betaScopes[0] = "changed";
gammaScopes.push("new");
assertArrayEqual(result.get("alpha") ?? [], ["read", "write", "read", "admin", "write"], "alpha result must be a snapshot");
assertArrayEqual(result.get("beta") ?? [], ["audit"], "beta result must be a snapshot");
assertArrayEqual(result.get("gamma") ?? [], [], "empty result bucket must be independent");
