export function encodeTaggedRecords(records: ReadonlyArray<{ priority: number; kind: number; flags: readonly boolean[]; payload: Uint8Array }>): Uint8Array;

Each input has a `kind` from 0 through 255, exactly eight flags, a payload of at most 255 bytes, and an integer priority. Encode records in ascending priority order. Records with equal priorities must retain their original relative order.

Encode each record as `kind`, a one-byte flag mask, payload length, payload bytes, and a checksum byte. Flag index `i` controls bit `i` of the mask. The checksum is the bitwise XOR of every preceding byte in that record, including the three header bytes. Concatenate the encoded records without a global header; an empty input produces an empty array. Inputs satisfy the stated ranges, so validation is unnecessary.

Use only deterministic standard-language facilities. Do not access the filesystem, network, clock, or randomness, and do not use external packages.","reference_code":"export function encodeTaggedRecords(
    records: ReadonlyArray<{
        priority: number;
        kind: number;
        flags: readonly boolean[];
        payload: Uint8Array;
    }>,
): Uint8Array {
    const ordered = records
        .map((record, index) => ({ record, index }))
        .sort((a, b) =>
            a.record.priority === b.record.priority
                ? a.index - b.index
                : a.record.priority - b.record.priority,
        );

    let totalLength = 0;
    for (const { record } of ordered) {
        totalLength += 4 + record.payload.length;
    }

    const output = new Uint8Array(totalLength);
    let offset = 0;

    for (const { record } of ordered) {
        let mask = 0;
        for (let bit = 0; bit < 8; bit++) {
            if (record.flags[bit]) {
                mask |= 1 << bit;
            }
        }

        const length = record.payload.length;
        let checksum = record.kind ^ mask ^ length;
        output[offset++] = record.kind;
        output[offset++] = mask;
        output[offset++] = length;

        for (const byte of record.payload) {
            output[offset++] = byte;
            checksum ^= byte;
        }

        output[offset++] = checksum;
    }

    return output;
}
