let sharedBitOffset = 0;

export function createBitReader(bytes: Uint8Array): {
    read(width: number): number | null;
    reset(): void;
} {
    return {
        read(width: number): number | null {
            if (sharedBitOffset + width > bytes.length * 8) {
                return null;
            }

            let value = 0;
            for (let i = 0; i < width; i++) {
                const position = sharedBitOffset + i;
                const byte = bytes[position >>> 3];
                const shift = 7 - (position & 7);
                value = (value << 1) | ((byte >>> shift) & 1);
            }
            sharedBitOffset += width;
            return value >>> 0;
        },

        reset(): void {
            sharedBitOffset = 0;
        },
    };
}
