export function collectOutcomes(tasks: ReadonlyArray<(report: (ok: boolean) => void) => void>, complete: (summary: { succeeded: number; failed: number }) => void): void;

Invoke every task exactly once, passing it a `report` callback. A task completes on its first call to `report`; any later calls by that same task are duplicates and must have no effect. After every task has reported once, invoke `complete` exactly once with the number of successful and failed tasks. If the task list is empty, invoke `complete` immediately with both counts set to zero. Tasks may report synchronously or later, and each task is guaranteed to report at least once.

Use only deterministic standard-language facilities. Do not access the filesystem, network, clock, or randomness, and do not use external packages.","reference_code":"export function collectOutcomes(
    tasks: ReadonlyArray<(report: (ok: boolean) => void) => void>,
    complete: (summary: { succeeded: number; failed: number }) => void,
): void {
    if (tasks.length === 0) {
        complete({ succeeded: 0, failed: 0 });
        return;
    }

    const settled = new Array<boolean>(tasks.length).fill(false);
    let completed = 0;
    let succeeded = 0;
    let failed = 0;

    tasks.forEach((task, index) => {
        task((ok: boolean): void => {
            if (settled[index]) {
                return;
            }
            settled[index] = true;

            if (ok) {
                succeeded++;
            } else {
                failed++;
            }
            completed++;

            if (completed === tasks.length) {
                complete({ succeeded, failed });
            }
        });
    });
}
