function assert(condition: boolean, message: string): void {
    if (!condition) throw new Error(message);
}

function assertBytes(actual: Uint8Array, expected: readonly number[], message: string): void {
    assert(actual.length === expected.length, `${message}: length ${actual.length} !== ${expected.length}`);
    for (let i = 0; i < expected.length; i++) {
        assert(actual[i] === expected[i], `${message}: byte ${i} was ${actual[i]}, expected ${expected[i]}`);
    }
}

const noFlags = [false, false, false, false, false, false, false, false] as const;

assertBytes(encodeTaggedRecords([]), [], 'empty input');

const payloadA = new Uint8Array([0xaa, 0x55]);
const payloadB = new Uint8Array([]);
const records = [
    { priority: 10, kind: 0x12, flags: [true, false, true, false, false, false, false, true], payload: payloadA },
    { priority: -3, kind: 0xff, flags: noFlags, payload: payloadB },
];
const recordsSnapshot = records.slice();
const payloadASnapshot = Array.from(payloadA);

assertBytes(
    encodeTaggedRecords(records),
    [0xff, 0x00, 0x00, 0xff, 0x12, 0x85, 0x02, 0xaa, 0x55, 0x6a],
    'sorting, flag packing, payload, and checksum',
);
assert(records[0] === recordsSnapshot[0] && records[1] === recordsSnapshot[1], 'input records were reordered or replaced');
assertBytes(payloadA, payloadASnapshot, 'payload was mutated');

const equalPriority = [
    { priority: 4, kind: 1, flags: noFlags, payload: new Uint8Array() },
    { priority: 4, kind: 2, flags: [true, false, false, false, false, false, false, false], payload: new Uint8Array() },
    { priority: 4, kind: 3, flags: noFlags, payload: new Uint8Array() },
];
assertBytes(
    encodeTaggedRecords(equalPriority),
    [1, 0, 0, 1, 2, 1, 0, 3, 3, 0, 0, 3],
    'equal-priority records retain their relative order',
);

const maximumPayload = new Uint8Array(255);
for (let i = 0; i < maximumPayload.length; i++) maximumPayload[i] = i;
const maximumSnapshot = Array.from(maximumPayload);
const maximumEncoded = encodeTaggedRecords([
    { priority: 0, kind: 0, flags: [true, true, true, true, true, true, true, true], payload: maximumPayload },
]);
assert(maximumEncoded.length === 259, 'maximum payload record has incorrect encoded length');
assert(maximumEncoded[0] === 0 && maximumEncoded[1] === 0xff && maximumEncoded[2] === 0xff, 'boundary header is incorrect');
for (let i = 0; i < 255; i++) {
    assert(maximumEncoded[i + 3] === i, `maximum payload byte ${i} is incorrect`);
}
assert(maximumEncoded[258] === 0xff, 'maximum payload checksum is incorrect');
assertBytes(maximumPayload, maximumSnapshot, 'maximum payload was mutated');

const first = encodeTaggedRecords(equalPriority);
const second = encodeTaggedRecords(equalPriority);
assert(first !== second, 'separate invocations should return separate arrays');
assertBytes(second, Array.from(first), 'repeated invocation is unstable');"},{"id":"cap-v2-binary_and_bitwise-typescript-repair-01","test_code":"import { createBitReader } from './solution';

function assert(condition: boolean, message: string): void {
    if (!condition) throw new Error(message);
}

const reader = createBitReader(new Uint8Array([0xb2, 0x61]));
assert(reader.read(3) === 5, 'first three MSB-first bits');
assert(reader.read(5) === 18, 'remaining bits of first byte');
assert(reader.read(4) === 6, 'first nibble of second byte');
assert(reader.read(4) === 1, 'second nibble of second byte');
assert(reader.read(1) === null, 'read past end should return null');

reader.reset();
assert(reader.read(8) === 0xb2, 'reset should return reader to its beginning');

const failedRead = createBitReader(new Uint8Array([0xab]));
assert(failedRead.read(5) === 21, 'prefix before failed read');
assert(failedRead.read(4) === null, 'insufficient read should return null');
assert(failedRead.read(3) === 3, 'insufficient read must not advance cursor');

const empty = createBitReader(new Uint8Array());
assert(empty.read(1) === null, 'empty reader');
empty.reset();
assert(empty.read(32) === null, 'reset empty reader');

const fullWidth = createBitReader(new Uint8Array([0xff, 0x00, 0x00, 0x01]));
assert(fullWidth.read(32) === 0xff000001, '32-bit result must be unsigned');
assert(fullWidth.read(1) === null, '32-bit read should consume all bits');

const first = createBitReader(new Uint8Array([0x80, 0x40]));
const second = createBitReader(new Uint8Array([0x7f]));
assert(first.read(1) === 1, 'first reader initial bit');
assert(second.read(1) === 0, 'second reader must have an independent cursor');
assert(first.read(7) === 0, 'first reader cursor changed by second reader');
assert(second.read(7) === 127, 'second reader remaining bits');
first.reset();
assert(first.read(8) === 0x80, 'reset first reader');
assert(second.read(1) === null, 'resetting first reader must not reset second reader');

const source = new Uint8Array([0xa5, 0x5a]);
const sourceSnapshot = Array.from(source);
const nonMutatingReader = createBitReader(source);
assert(nonMutatingReader.read(16) === 0xa55a, 'whole source read');
assert(source[0] === sourceSnapshot[0] && source[1] === sourceSnapshot[1], 'reader mutated source bytes');"},{"id":"cap-v2-binary_and_bitwise-typescript-repair-02","test_code":"import { crc8Chunks } from './solution';

function assert(condition: boolean, message: string): void {
    if (!condition) throw new Error(message);
}

function ascii(text: string): Uint8Array {
    const result = new Uint8Array(text.length);
    for (let i = 0; i < text.length; i++) result[i] = text.charCodeAt(i);
    return result;
}

assert(crc8Chunks([]) === 0, 'empty chunk list should produce zero');
assert(crc8Chunks([new Uint8Array(), new Uint8Array()]) === 0, 'empty chunks should produce zero');
assert(crc8Chunks([new Uint8Array([0])]) === 0, 'single zero byte');
assert(crc8Chunks([new Uint8Array([0x80])]) === 0x89, 'MSB and polynomial processing');

const checkVector = ascii('123456789');
assert(crc8Chunks([checkVector]) === 0xf4, 'standard CRC-8 check vector');
assert(
    crc8Chunks([ascii('12'), new Uint8Array(), ascii('345'), ascii('6789')]) === 0xf4,
    'chunk boundaries must not alter CRC',
);

crc8Chunks([new Uint8Array([0xff, 0x01, 0x7e])]);
assert(crc8Chunks([]) === 0, 'a later empty call must start from zero');
assert(crc8Chunks([checkVector]) === 0xf4, 'separate calls must not influence each other');

const chunks = [new Uint8Array([1, 2, 3]), new Uint8Array([254, 255])];
const snapshots = chunks.map((chunk) => Array.from(chunk));
const first = crc8Chunks(chunks);
const second = crc8Chunks(chunks);
assert(first === second, 'same input should produce a stable result');
for (let c = 0; c < chunks.length; c++) {
    assert(chunks[c].length === snapshots[c].length, `chunk ${c} length was mutated`);
    for (let i = 0; i < chunks[c].length; i++) {
        assert(chunks[c][i] === snapshots[c][i], `chunk ${c}, byte ${i} was mutated`);
    }
}"},{"id":"cap-v2-callbacks_and_events-typescript-generation-01","test_code":"import { collectOutcomes } from './solution';

function assert(condition: boolean, message: string): void {
    if (!condition) throw new Error(message);
}

let emptyCompletions = 0;
collectOutcomes([], (summary) => {
    emptyCompletions++;
    assert(summary.succeeded === 0 && summary.failed === 0, 'empty summary');
});
assert(emptyCompletions === 1, 'empty input must complete immediately exactly once');

let invocationCount = 0;
let synchronousCompletions = 0;
collectOutcomes(
    [
        (report) => { invocationCount++; report(true); report(false); },
        (report) => { invocationCount++; report(false); report(true); report(false); },
        (report) => { invocationCount++; report(true); },
    ],
    (summary) => {
        synchronousCompletions++;
        assert(summary.succeeded === 2, 'synchronous success count');
        assert(summary.failed === 1, 'synchronous failure count');
    },
);
assert(invocationCount === 3, 'every synchronous task must be invoked exactly once');
assert(synchronousCompletions === 1, 'synchronous completion must occur exactly once');

const pending: Array<(ok: boolean) => void> = [];
let mixedInvocations = 0;
let mixedCompletions = 0;
collectOutcomes(
    [
        (report) => { mixedInvocations++; pending.push(report); },
        (report) => { mixedInvocations++; report(true); pending.push(report); },
        (report) => { mixedInvocations++; pending.push(report); },
    ],
    (summary) => {
        mixedCompletions++;
        assert(summary.succeeded === 2 && summary.failed === 1, 'mixed timing summary');
    },
);
assert(mixedInvocations === 3, 'all tasks must be invoked without waiting for earlier reports');
assert(mixedCompletions === 0, 'must not complete while reports are outstanding');
pending[0](false);
assert(mixedCompletions === 0, 'must wait for final distinct task');
pending[1](false);
pending[1](true);
assert(mixedCompletions === 0, 'duplicate report must not complete early');
pending[2](true);
assert(mixedCompletions === 1, 'must complete after every task reports');
pending[0](true);
pending[2](false);
assert(mixedCompletions === 1, 'late duplicate reports must be ignored');

const tasks = [
    (report: (ok: boolean) => void): void => report(true),
    (report: (ok: boolean) => void): void => report(false),
];
const snapshot = tasks.slice();
collectOutcomes(tasks, () => {});
assert(tasks.length === 2 && tasks[0] === snapshot[0] && tasks[1] === snapshot[1], 'task array was mutated');"},{"id":"cap-v2-callbacks_and_events-typescript-generation-02","test_code":"import { broadcastOnce } from './solution';

function assert(condition: boolean, message: string): void {
    if (!condition) throw new Error(message);
}

let emptyCompletions = 0;
broadcastOnce('empty', [], () => { emptyCompletions++; });
assert(emptyCompletions === 1, 'empty listener list must complete immediately exactly once');

let firstCalls = 0;
let secondCalls = 0;
let synchronousCompletions = 0;
const firstListener = (message: string, acknowledge: () => void): void => {
    firstCalls++;
    assert(message === 'hello', 'first listener received wrong message');
    acknowledge();
    acknowledge();
};
const secondListener = (message: string, acknowledge: () => void): void => {
    secondCalls++;
    assert(message === 'hello', 'second listener received wrong message');
    acknowledge();
};
const registrations = [firstListener, firstListener, secondListener, firstListener, secondListener];
const registrationSnapshot = registrations.slice();
broadcastOnce('hello', registrations, () => { synchronousCompletions++; });
assert(firstCalls === 1 && secondCalls === 1, 'duplicate listener registrations must be invoked once');
assert(synchronousCompletions === 1, 'synchronous acknowledgements must complete exactly once');
assert(
    registrations.length === registrationSnapshot.length && registrations.every((value, index) => value === registrationSnapshot[index]),
    'listener registrations were mutated',
);

const acknowledgements: Array<() => void> = [];
let delayedFirstCalls = 0;
let delayedSecondCalls = 0;
let delayedCompletions = 0;
const delayedFirst = (message: string, acknowledge: () => void): void => {
    delayedFirstCalls++;
    assert(message === '', 'empty message must be forwarded unchanged');
    acknowledgements.push(acknowledge);
};
const delayedSecond = (message: string, acknowledge: () => void): void => {
    delayedSecondCalls++;
    assert(message === '', 'second listener received wrong message');
    acknowledgements.push(acknowledge);
};
broadcastOnce('', [delayedFirst, delayedSecond, delayedFirst], () => { delayedCompletions++; });
assert(delayedFirstCalls === 1 && delayedSecondCalls === 1, 'distinct delayed listeners invocation count');
assert(acknowledgements.length === 2, 'each distinct listener must receive an acknowledgement callback');
assert(acknowledgements[0] !== acknowledgements[1], 'listeners must receive their own acknowledgement callbacks');
assert(delayedCompletions === 0, 'must wait for acknowledgements');
acknowledgements[0]();
acknowledgements[0]();
assert(delayedCompletions === 0, 'duplicate acknowledgement must not count twice');
acknowledgements[1]();
assert(delayedCompletions === 1, 'must complete after all distinct listeners acknowledge');
acknowledgements[1]();
acknowledgements[0]();
assert(delayedCompletions === 1, 'late acknowledgements must not repeat completion');

let identityCalls = 0;
const makeListener = (): ((message: string, acknowledge: () => void) => void) =>
    (_message, acknowledge) => { identityCalls++; acknowledge(); };
const identityA = makeListener();
const identityB = makeListener();
let identityCompletions = 0;
broadcastOnce('same behavior, different identity', [identityA, identityB], () => { identityCompletions++; });
assert(identityCalls === 2, 'different function objects must remain distinct listeners');
assert(identityCompletions === 1, 'identity boundary completion');"}]}

